/** Static foot-end T rails derived solely from the selected Root paths.
 * The same parts and grounded steel brackets serve rendering and actual
 * triangle admission. Reading this source does not install or enable it. */
public final class NervFixedFootGuidesR52 {
 public static final String SOURCE="facility/r52_ground_guide_paths.json",SOURCE_SHA="e09fe5a920585e1ae12df8b27a55d53102550c33c84b5c1009e58ee890a3e287";
 public record Anchor(String path,BlockPos at,String state,Vec3 actualBearing){}
 public record Path(String id,String reverse,int variant,String motion,RigidTransform from,RigidTransform to,Quaternionf bodyFrom,Quaternionf bodyTo,List<String> rails,String support,List<String> gates,boolean cutStart,boolean cutEnd){}
 private record Door(RigidTransform frame,SiloHatchMechanism.Spec spec){}
 private static List<Path> paths;private static List<NervServiceFootDriveR52.Piece> pieces;private static List<Anchor> anchors;private static Map<String,Path> byLeg;
 private static NervStaticSpatialIndexR52<NervServiceFootDriveR52.Piece> spatial;
 private static final Map<ServerLevel,String> ENABLED=new WeakHashMap<>();
 public static synchronized void install()throws IOException {
  if(paths!=null)return;var bytes=EvaOriginalMeshGeometryR52.classpathBytes(SOURCE);try{if(!HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes)).equals(SOURCE_SHA))throw new IllegalStateException("Root actual foot-guide paths changed");}catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}var j=JsonParser.parseString(new String(bytes,StandardCharsets.UTF_8)).getAsJsonObject();if(!j.get("schema").getAsString().equals("projectseele.r52.root-derived-foot-guides.v1")||!j.get("rig_source_sha256").getAsString().equals(NervFootGuideRigR52.SOURCE_SHA))throw new IllegalStateException("Selected Root path/actual guide rig pair required");
  var all=new ArrayList<Path>();var lookup=new HashMap<String,Path>();for(var raw:j.getAsJsonArray("paths")){var p=raw.getAsJsonObject();var row=new Path(p.get("leg").getAsString(),p.get("reverse_leg").getAsString(),p.get("variant").getAsInt(),p.get("motion").getAsString(),frame(p.getAsJsonObject("from")),frame(p.getAsJsonObject("to")),quaternion(p.getAsJsonArray("body_from")),quaternion(p.getAsJsonArray("body_to")),strings(p.getAsJsonArray("rail_ids")),p.get("support_id").getAsString(),strings(p.getAsJsonArray("gates")),p.get("start_turn_cut").getAsBoolean(),p.get("end_turn_cut").getAsBoolean());if(lookup.putIfAbsent(row.id(),row)!=null||lookup.putIfAbsent(row.reverse(),row)!=null)throw new IllegalStateException("Actual forward/reverse guide declaration must be unique");all.add(row);}
  if(all.size()!=21)throw new IllegalStateException("The twenty-one Root vertical/inclined guide paths are required");var doors=new ArrayList<Door>();for(var raw:j.getAsJsonArray("silo_gates")){var d=raw.getAsJsonObject();var s=d.getAsJsonObject("silo_hatch");doors.add(new Door(frameGate(d.getAsJsonObject("frame")),new SiloHatchMechanism.Spec(s.get("opening_x").getAsFloat(),s.get("opening_z").getAsFloat(),s.get("open_ticks").getAsInt(),s.get("close_ticks").getAsInt(),s.get("separation_sign").getAsInt(),s.get("beam_bottom").getAsDouble(),s.get("service_column_ports").getAsBoolean())));}
  var elbowSpec=j.getAsJsonObject("engineered_anchor_elbows");if(elbowSpec==null||elbowSpec.get("raise_m").getAsDouble()!=1||elbowSpec.get("riser_width_m").getAsDouble()!=.05||elbowSpec.get("riser_depth_m").getAsDouble()!=.12)throw new IllegalStateException("Root approved finite elbow source required");var elbows=new HashSet<BlockPos>();for(var raw:elbowSpec.getAsJsonArray("original_cells")){var a=raw.getAsJsonArray();if(a.size()!=3||!elbows.add(new BlockPos(a.get(0).getAsInt(),a.get(1).getAsInt(),a.get(2).getAsInt())))throw new IllegalStateException("Unique exact Root elbow cells required");}if(elbows.size()!=6)throw new IllegalStateException("Six Root approved elbow anchors required");var appliedElbows=new HashSet<BlockPos>();var steel=new ArrayList<NervServiceFootDriveR52.Piece>();var pads=new ArrayList<Anchor>();double span=j.get("maximum_supported_span_m").getAsDouble();if(span<=0||span>16)throw new IllegalStateException("Finite actual bracket pitch required");for(var path:all)build(path,doors,span,j.get("native_anchor_state").getAsString(),steel,pads,elbows,appliedElbows);if(!appliedElbows.equals(elbows))throw new IllegalStateException("Every Root elbow must match an actual derived spine anchor");paths=List.copyOf(all);byLeg=Map.copyOf(lookup);pieces=List.copyOf(steel);anchors=List.copyOf(pads);spatial=new NervStaticSpatialIndexR52<>(pieces,p->p.mesh().envelope(p.frame(),p.frame()));
 }
 private static Vec3 point(JsonArray a){return new Vec3(a.get(0).getAsDouble(),a.get(1).getAsDouble(),a.get(2).getAsDouble());}
 private static Quaternionf quaternion(JsonArray a){return new Quaternionf(a.get(0).getAsFloat(),a.get(1).getAsFloat(),a.get(2).getAsFloat(),a.get(3).getAsFloat());}
 private static RigidTransform frame(JsonObject p){return RigidTransform.of(point(p.getAsJsonArray("translation")),quaternion(p.getAsJsonArray("quaternion_xyzw")));}
 private static RigidTransform frameGate(JsonObject p){return RigidTransform.of(point(p.getAsJsonArray("position")),quaternion(p.getAsJsonArray("quaternion")));}
 private static List<String> strings(JsonArray a){var out=new ArrayList<String>();a.forEach(v->out.add(v.getAsString()));return List.copyOf(out);}
 private static List<double[]> outside(double low,double high,List<double[]> cuts){var pieces=new ArrayList<double[]>();pieces.add(new double[]{low,high});for(var cut:cuts){var next=new ArrayList<double[]>();for(var p:pieces){if(cut[1]<=p[0]||cut[0]>=p[1])next.add(p);else {if(cut[0]>p[0])next.add(new double[]{p[0],cut[0]});if(cut[1]<p[1])next.add(new double[]{cut[1],p[1]});}}pieces=next;}return List.copyOf(pieces);}
 private static void build(Path path,List<Door> doors,double span,String state,List<NervServiceFootDriveR52.Piece> steel,List<Anchor> pads,Set<BlockPos> elbows,Set<BlockPos> appliedElbows)throws IOException {
  var b=NervFootGuideRigR52.nominalBinding(path.variant());var sample=FootSupportFrameR52.sample(b,path.from(),path.bodyFrom(),path.bodyTo(),0);var axis=sample.rightContact().subtract(sample.leftContact()).normalize();var delta=path.to().translation().subtract(path.from().translation());double length=delta.length();var up=delta.normalize();var normal=axis.subtract(up.scale(axis.dot(up))).normalize();
  for(int side:new int[]{-1,1}){var centre=path.from().translation().add(axis.subtract(normal).scale(side*NervFootGuideRigR52.AXIS_EXTENSION));var root=NervFootGuideRigR52.bearingFrame(centre,normal,up);var headCuts=new ArrayList<double[]>();var backingCuts=new ArrayList<double[]>();for(var door:doors){if(door.spec().separationSign()!=1||path.motion().equals("LAUNCH_INCLINE"))continue;var inverse=door.frame().inverse();var p=inverse.transformPoint(path.from().translation());var q=inverse.transformPoint(path.to().translation());if(Math.abs(p.x)>1||Math.abs(q.x)>1||Math.abs(p.z)>1.5||Math.abs(q.z)>1.5)continue;double at=root.inverse().transformPoint(door.frame().translation()).y;headCuts.add(new double[]{at-.10,at+door.spec().maximumTier()+.98+.08});backingCuts.add(new double[]{at+door.spec().beamBottom()-.08,at+door.spec().maximumTier()+.98+.08});}
   double start=path.cutStart()?NervFootGuideDockR52.TURN_CLEARANCE:-3.35,finish=path.cutEnd()?length-NervFootGuideDockR52.TURN_CLEARANCE:length+3.35;int index=0;for(double y=start;y<finish;y+=span){double end=Math.min(finish,y+span);for(int component=0;component<8;component++)for(var interval:outside(y,end,component==0?headCuts:backingCuts)){double segmentMid=(interval[0]+interval[1])*.5;var segmentFrame=root.compose(new RigidTransform(new Vec3(0,segmentMid,0),0,0,0,1));var guide=NervServiceFootDriveR52.tGuide("ground_rail/"+path.id()+"/"+(index++)+"/"+side,side,interval[0]-segmentMid,interval[1]-segmentMid,segmentFrame,false).get(component);steel.add(guide);if(component==3){double mid=(interval[0]+interval[1])*.5;var outside=root.transformPoint(new Vec3(side*18.25,mid,.8));var at=BlockPos.containing(outside);boolean raisedElbow=elbows.contains(at);if(raisedElbow){appliedElbows.add(at);at=at.above();}var bearing=new Vec3(at.getX()+.5,at.getY()+1,at.getZ()+.5);pads.add(new Anchor(path.id(),at,state,bearing));var foot=RigidTransform.of(bearing,new Quaternionf());steel.add(NervServiceFootDriveR52.box("ground_anchor/"+path.id()+"/"+index,new AABB(-.2,0,-.2,.2,.12,.2),foot,false));var first=root.transformPoint(new Vec3(side*(NervFootGuideRigR52.AXIS_EXTENSION+1.20),mid,.8));if(raisedElbow){double x=side*(NervFootGuideRigR52.AXIS_EXTENSION+1.175);steel.add(NervServiceFootDriveR52.box("ground_bracket_riser/"+path.id()+"/"+index,new AABB(-.025,-.5,-.06,.025,.5,.06),root.compose(new RigidTransform(new Vec3(x,mid+.5,.8),0,0,0,1)),false));first=root.transformPoint(new Vec3(x,mid+1,.8));}var last=bearing.add(0,.12,0);var direction=last.subtract(first);var arm=NervCranePoseR52.ropeFrame(first,last);steel.add(NervServiceFootDriveR52.box("ground_bracket/"+path.id()+"/"+index,new AABB(-.06,0,-.06,.06,direction.length(),.06),arm,false));}}
   }
  }
 }
 public static List<Path> paths()throws IOException {install();return paths;}
 public static List<NervServiceFootDriveR52.Piece> pieces()throws IOException {install();return pieces;}
 public static List<Anchor> anchors()throws IOException {install();return anchors;}
 public static Vec3 up(NervRouteDirectoryR52 d,NervRouteDirectoryR52.Leg l)throws IOException {install();var path=byLeg.get(l.id());return path==null?null:path.to().translation().subtract(path.from().translation()).normalize();}
 public static boolean matchesDirectory(NervRouteDirectoryR52 d)throws IOException {install();for(var p:paths){var l=d.leg(p.id());var reverse=d.leg(p.reverse());if(l==null||reverse==null||!l.motion().name().equals(p.motion())||!d.node(l.from()).footFrame().equals(p.from())||!d.node(l.to()).footFrame().equals(p.to())||!l.evaFrom().quaternion().equals(p.bodyFrom())||!l.evaTo().quaternion().equals(p.bodyTo())||!l.rails().equals(p.rails())||!l.support().equals(p.support())||p.cutStart()!=NervFootGuideDockR52.cutStartR52(d,l)||p.cutEnd()!=NervFootGuideDockR52.cutEndR52(d,l))return false;}return true;}
 public static String firstMissingAnchor(ServerLevel l)throws IOException {install();for(var a:anchors){if(!l.hasChunkAt(a.at()))return "path="+a.path()+" at="+a.at()+" expected="+a.state()+" current=UNLOADED";var state=l.getBlockState(a.at());if(!state.getBlock().builtInRegistryHolder().key().location().toString().equals(a.state()))return "path="+a.path()+" at="+a.at()+" expected="+a.state()+" current="+state;boolean bearing=false;for(var box:state.getCollisionShape(l,a.at()).toAabbs()){var b=box.move(a.at());var p=a.actualBearing();if(Math.abs(b.maxY-p.y)<.002&&p.x-b.minX>=.2&&b.maxX-p.x>=.2&&p.z-b.minZ>=.2&&b.maxZ-p.z>=.2)bearing=true;}if(!bearing)return "path="+a.path()+" at="+a.at()+" missing_actual_finite_top="+a.actualBearing();}return "MATCH";}
 public static synchronized void enable(ServerLevel l,NervRouteDirectoryR52 d)throws IOException {if(!matchesDirectory(d)||!firstMissingAnchor(l).equals("MATCH"))throw new IllegalStateException("Actual Root paths and finite native rail-anchor bearing required");ENABLED.put(l,d.fingerprint());}
 public static boolean enabledForDirectoryR52(ServerLevel l,NervRouteDirectoryR52 d){return d.fingerprint().equals(ENABLED.get(l));}
 public static boolean pathAnchorsBearR52(ServerLevel l,String path)throws IOException {install();boolean found=false;for(var a:anchors)if(a.path().equals(path)){found=true;if(l.getChunkSource().getChunkNow(a.at().getX()>>4,a.at().getZ()>>4)==null)return false;var state=l.getBlockState(a.at());if(!net.minecraft.commands.arguments.blocks.BlockStateParser.serialize(state).equals(a.state()))return false;boolean bearing=false;for(var box:state.getCollisionShape(l,a.at()).toAabbs()){var b=box.move(a.at());var p=a.actualBearing();if(Math.abs(b.maxY-p.y)<.002&&p.x-b.minX>=.2&&b.maxX-p.x>=.2&&p.z-b.minZ>=.2&&b.maxZ-p.z>=.2)bearing=true;}if(!bearing)return false;}return found;}
 public static List<NervServiceFootDriveR52.Piece> actualPieces(ServerLevel l,AABB query)throws IOException {if(!ENABLED.containsKey(l))return List.of();install();return spatial.query(query);}
 public static List<NervFlightProofR52.ObstacleMesh> actualMeshes(ServerLevel l,AABB query)throws IOException {if(!ENABLED.containsKey(l))return List.of();var out=new ArrayList<NervFlightProofR52.ObstacleMesh>();install();for(var p:spatial.query(query))out.add(new NervFlightProofR52.ObstacleMesh(p.mesh(),p.frame()));return List.copyOf(out);}
 private NervFixedFootGuidesR52(){}
}
